For the JavaScript, I need to initialize all the AntV Infographic instances and signal when they're done:

```javascript
const instances = [];
const totalCharts = 5;
let renderedCount = 0;

function createInfographic(containerId, syntax) {
    const instance = new AntVInfographic.Infographic({
        container: '#' + containerId,
        width: '100%',
        height: '100%',
    });
    instance.render(syntax);
    instances.push(instance);
}

// Recovery Overview
createInfographic('recovery-chart', `infographic compare-binary-horizontal-underline-text-vs
data
  title ...
  compares
    - label ...
`);

// Risks
createInfographic('risks-chart', `infographic list-grid-badge-card
data
  title ...
  lists
    - label ...
`);

// ... etc

// Re-render after fonts load
document.fonts?.ready.then(() => {
    instances.forEach(instance => instance.render(/* need to store syntax too */));
    window.infographicsReady = true;
}).catch(() => {
    window.infographicsReady = true;
});
```

Wait, I need to store the syntax for each instance so I can re-render. Let me adjust:

```javascript
const chartConfigs = [
    { id: 'recovery-chart', syntax: `...` },
    { id: 'risks-chart', syntax: `...` },
    { id: 'policy-chart', syntax: `...` },
    { id: 'priorities-chart', syntax: `...` },
    { id: 'research-chart', syntax: `...` },
];

chartConfigs.forEach(config => {
    const instance = new AntVInfographic.Infographic({
        container: '#' + config.id,
        width: '100%',
        height: '100%',
    });
    instance.render(config.syntax);
    config.instance = instance;
});

document.fonts?.ready.then(() => {
    chartConfigs.forEach(config => {
        config.instance.render(config.syntax);
    });
    setTimeout(() => {
        window.infographicsReady = true;
    }, 1000);
}).catch(() => {
    window.infographicsReady = true;
});
```

