(async () => {
    const browser = await puppeteer.launch({
        headless: 'new',
        args: ['--no-sandbox', '--disable-setuid-sandbox', '--disable-dev-shm-usage'],
    });
    const page = await browser.newPage();

    // Set viewport for A1 proportions at high resolution
    await page.setViewport({
        width: 1200,
        height: 1697,
        deviceScaleFactor: 3,
    });

    // Open the HTML file
    const htmlPath = path.resolve('/app/poster.html');
    await page.goto(`file://${htmlPath}`, {
        waitUntil: 'networkidle0',
        timeout: 30000,
    });

    // Wait for infographics to render
    try {
        await page.waitForFunction('window.infographicsReady === true', {
            timeout: 15000,
        });
    } catch (e) {
        console.log('Timeout waiting for infographics, proceeding anyway...');
    }

    // Extra wait for SVG rendering to complete
    await new Promise(resolve => setTimeout(resolve, 2000));

    // Take screenshot of the full page
    await page.screenshot({
        path: '/app/output/final_poster.png',
        fullPage: true,
        type: 'png',
    });

    await browser.close();
    console.log('Poster rendered successfully to /app/output/final_poster.png');
})();

