const puppeteer = require('puppeteer');
const path = require('path');

(async () => {
    const browser = await puppeteer.launch({
        headless: 'new',
        args: ['--no-sandbox', '--disable-setuid-sandbox', '--disable-dev-shm-usage'],
    });
    const page = await browser.newPage();

    // Capture console messages
    page.on('console', msg => {
        console.log('CONSOLE:', msg.type(), msg.text());
    });
    page.on('pageerror', err => {
        console.log('PAGE ERROR:', err.message);
    });

    await page.setViewport({
        width: 1200,
        height: 1697,
        deviceScaleFactor: 3,
    });

    const htmlPath = path.resolve('/app/poster.html');
    await page.goto(`file://${htmlPath}`, {
        waitUntil: 'networkidle0',
        timeout: 30000,
    });

    // Wait for infographics
    try {
        await page.waitForFunction('window.infographicsReady === true', { timeout: 15000 });
    } catch (e) {
        console.log('Timeout waiting for infographics ready flag');
    }

    await new Promise(resolve => setTimeout(resolve, 2000));

    // Check for SVG elements in each chart container
    const chartStatus = await page.evaluate(() => {
        const ids = ['recovery-chart', 'risks-chart', 'policy-chart', 'priorities-chart', 'research-chart'];
        const results = {};
        ids.forEach(id => {
            const el = document.getElementById(id);
            if (!el) {
                results[id] = 'NOT FOUND';
                return;
            }
            const svgs = el.querySelectorAll('svg');
            const children = el.children.length;
            const innerHTML = el.innerHTML.substring(0, 200);
            results[id] = { svgCount: svgs.length, childCount: children, innerHTML: innerHTML };
        });
        return results;
    });

    console.log('\nChart rendering status:');
    console.log(JSON.stringify(chartStatus, null, 2));

    await browser.close();
})();

