const puppeteer = require('puppeteer');
const path = require('path');

(async () => {
    const browser = await puppeteer.launch({
        headless: 'new',
        args: ['--no-sandbox', '--disable-setuid-sandbox', '--disable-dev-shm-usage'],
    });
    const page = await browser.newPage();

    page.on('console', msg => {
        if (msg.type() === 'error') console.log('CONSOLE ERROR:', msg.text());
    });
    page.on('pageerror', err => {
        console.log('PAGE ERROR:', err.message);
    });

    await page.setViewport({ width: 1200, height: 1697, deviceScaleFactor: 1 });

    const htmlPath = path.resolve('/app/poster.html');
    await page.goto(`file://${htmlPath}`, { waitUntil: 'networkidle0', timeout: 30000 });

    try {
        await page.waitForFunction('window.infographicsReady === true', { timeout: 15000 });
    } catch (e) {
        console.log('Timeout waiting for infographics');
    }
    await new Promise(r => setTimeout(r, 2000));

    // Check each section
    const report = await page.evaluate(() => {
        const result = {};

        // 1. Header
        const h1 = document.querySelector('h1');
        const h2 = document.querySelector('h2');
        const badge = document.querySelector('.recovery-badge');
        result.header = {
            title: h1?.textContent,
            subtitle: h2?.textContent,
            badge: badge?.textContent?.trim(),
        };

        // 2. Metrics banner
        const metricsTitle = document.querySelector('.metrics-title');
        const metricCards = document.querySelectorAll('.metric-card');
        result.metrics = {
            sectionTitle: metricsTitle?.textContent,
            cardCount: metricCards.length,
            cards: Array.from(metricCards).map(c => ({
                value: c.querySelector('.metric-value')?.textContent,
                label: c.querySelector('.metric-label')?.textContent,
            })),
        };

        // 3. Section headers
        const sectionHeaders = document.querySelectorAll('.section-header h3');
        result.sectionHeaders = Array.from(sectionHeaders).map(h => h.textContent);

        // 4. Chart SVGs
        const chartIds = ['recovery-chart', 'risks-chart', 'policy-chart', 'priorities-chart', 'research-chart'];
        result.charts = {};
        chartIds.forEach(id => {
            const el = document.getElementById(id);
            const svg = el?.querySelector('svg');
            result.charts[id] = {
                exists: !!el,
                hasSVG: !!svg,
                svgWidth: svg?.getAttribute('width'),
                svgHeight: svg?.getAttribute('height'),
                containerHeight: el?.style.height,
            };
        });

        // 5. Risks section highlight
        const risksSection = document.querySelector('.risks-section');
        result.risksHighlighted = {
            hasBorder: risksSection?.style.border || getComputedStyle(risksSection)?.border,
            hasBackground: getComputedStyle(risksSection)?.backgroundColor,
        };

        // 6. Footer
        const footer = document.querySelector('.poster-footer p');
        result.footer = footer?.textContent;

        // 7. Page dimensions
        result.pageHeight = document.body.scrollHeight;

        return result;
    });

    console.log(JSON.stringify(report, null, 2));

    // Also take a lower-res screenshot for quick verification
    await page.setViewport({ width: 1200, height: 1697, deviceScaleFactor: 2 });
    await page.goto(`file://${htmlPath}`, { waitUntil: 'networkidle0', timeout: 30000 });
    try {
        await page.waitForFunction('window.infographicsReady === true', { timeout: 15000 });
    } catch (e) {}
    await new Promise(r => setTimeout(r, 2000));

    await page.screenshot({
        path: '/app/output/poster_preview.png',
        fullPage: true,
        type: 'png',
    });

    await browser.close();
    console.log('\nPreview saved to /app/output/poster_preview.png');
})();

