arguments.command:
node -e "
const puppeteer = require('puppeteer');
const path = require('path');
(async () => {
    const browser = await puppeteer.launch({ headless: 'new', args: ['--no-sandbox','--disable-setuid-sandbox','--disable-dev-shm-usage'] });
    const page = await browser.newPage();
    await page.setViewport({ width: 1200, height: 1697, deviceScaleFactor: 1 });
    await page.goto('file://' + path.resolve('/app/poster.html'), { waitUntil: 'networkidle0', timeout: 30000 });
    try { await page.waitForFunction('window.infographicsReady === true', { timeout: 15000 }); } catch(e) {}
    await new Promise(r => setTimeout(r, 2000));
    const ok = await page.evaluate(() => {
        const charts = ['recovery-chart','risks-chart','policy-chart','priorities-chart','research-chart'];
        const svgOk = charts.every(id => document.getElementById(id)?.querySelector('svg'));
        const metrics = document.querySelectorAll('.metric-card').length === 6;
        const header = document.querySelector('h1')?.textContent === 'Global Economic Prospects';
        const badge = document.querySelector('.recovery-badge')?.textContent?.includes('Strongest');
        const footer = document.querySelector('.poster-footer p')?.textContent?.includes('World Bank');
        return { svgOk, metrics, header, badge, footer, allGood: svgOk && metrics && header && badge && footer };
    });
    console.log(JSON.stringify(ok, null, 2));
    await browser.close();
})();
" 2>&1

